ver_+7.lua",["SHA256"]="b8b96bc8b644f052d982194019a577199a6b887f570c78ea41e41e7448704f11",["Text"]="-----------------------------------\n-- ID: 5277\n-- Old Quiver +7\n-- When used, you will obtain one partial stack of Crude Arrows +7\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.itemBoxOnItemCheck(target)\nend\n\nitemObject.onItemUse = function(target)\n    npcUtil.giveItem(target, { { xi.item.CRUDE_ARROW_P7, math.randomInt(10, 20) } })\nend\n\nreturn itemObject\n"},["scripts/items/olde_rarab_tail.lua"]={["Path"]="scripts/items/olde_rarab_tail.lua",["SHA256"]="4580cd37d58806ec94487bacdc39203014180055e6b2b4e7102b21f40d15130d",["Text"]="-----------------------------------\n-- ID: 5911\n-- Item: Olde Rarab Tail\n-- Effect: 90 Seconds of \"Terror\" effect.\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    local ID = zones[target:getZoneID()]\n\n    if\n        not target:hasStatusEffect(xi.effect.TERROR) and\n        (target:getID() == ID.mob.ATORI_TUTORI or\n        target:getID() == ID.mob.ATORI_TUTORI + 1 or\n        target:getID() == ID.mob.ATORI_TUTORI + 2)\n    then\n        target:addStatusEffect(xi.effect.TERROR, { power = 1, duration = 90, origin = user, tick = 3 })\n    else\n        target:messageBasic(xi.msg.basic.NO_EFFECT)\n    end\nend\n\nreturn itemObject\n"},["scripts/items/olduum_ring.lua"]={["Path"]="scripts/items/olduum_ring.lua",["SHA256"]="f1dc89bc5bf3c9253310e5318ccaf8bf13d46f7a87d23753bba8232267f4c6fa",["Text"]="-----------------------------------\n--   ID: 15769\n--   Olduum Ring\n--   Teleports to Wajoam Woodlands Leypoint\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    target:addStatusEffect(xi.effect.TELEPORT, { power = xi.teleport.id.WAJAOM_LEYPOINT, duration = 3, origin = user, icon = 0 })\nend\n\nreturn itemObject\n"},["scripts/items/omelette_sandwich.lua"]={["Path"]="scripts/items/omelette_sandwich.lua",["SHA256"]="e60125f737e23fbda2eef7a7e776fe2ed36811eb2783f99fdf987b2bfc812150",["Text"]="-----------------------------------\n-- ID: 6601\n-- Item: Omelette Sandwich\n-- Food Effect: 30minutes, All Races\n-----------------------------------\n-- HP +11% (Max. 150)\n-- VIT +7\n-- MND +7\n-- Accuracy +11% (Max. 80)\n-- DEF +11% (Max. 120)\n-- Enmity +4\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 1800, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.FOOD_HPP, 11)\n    effect:addMod(xi.mod.FOOD_HP_CAP, 150)\n    effect:addMod(xi.mod.VIT, 7)\n    effect:addMod(xi.mod.MND, 7)\n    effect:addMod(xi.mod.FOOD_ACCP, 11)\n    effect:addMod(xi.mod.FOOD_ACC_CAP, 80)\n    effect:addMod(xi.mod.FOOD_DEFP, 11)\n    effect:addMod(xi.mod.FOOD_DEF_CAP, 120)\n    effect:addMod(xi.mod.ENMITY, 4)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/omelette_sandwich_+1.lua"]={["Path"]="scripts/items/omelette_sandwich_+1.lua",["SHA256"]="1f99edb728e00e0dd270ee62024eba97df021f17258b9bec829b4a2e5c1958d2",["Text"]="-----------------------------------\n-- ID: 6602\n-- Item: Omelette Sandwich +1\n-- Food Effect: 30minutes, All Races\n-----------------------------------\n-- HP +11% (Max. 155)\n-- VIT +8\n-- MND +8\n-- Accuracy +11% (Max. 85)\n-- DEF +11% (Max. 125)\n-- Enmity +5\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 1800, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.FOOD_HPP, 11)\n    effect:addMod(xi.mod.FOOD_HP_CAP, 155)\n    effect:addMod(xi.mod.VIT, 8)\n    effect:addMod(xi.mod.MND, 8)\n    effect:addMod(xi.mod.FOOD_ACCP, 11)\n    effect:addMod(xi.mod.FOOD_ACC_CAP, 85)\n    effect:addMod(xi.mod.FOOD_DEFP, 11)\n    effect:addMod(xi.mod.FOOD_DEF_CAP, 125)\n    effect:addMod(xi.mod.ENMITY, 5)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/onago_yukata.lua"]={["Path"]="scripts/items/onago_yukata.lua",["SHA256"]="9e58dcaf2fc5a716710368b506fe622a74094d795387577f0b93ef918549c091",["Text"]="-----------------------------------\n-- ID: 14533\n-- onago_yukata\n-- Dispense: Muteppo x99\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.itemBoxOnItemCheck(target)\nend\n\nitemObject.onItemUse = function(target)\n    npcUtil.giveItem(target, { { xi.item.MUTEPPO, 99 } })\nend\n\nreturn itemObject\n"},["scripts/items/onnagimi_yukata.lua"]={["Path"]="scripts/items/onnagimi_yukata.lua",["SHA256"]="7a8b3681f09abc517e727209f740baacce35ed39c738b8be1e9eb31b583436f8",["Text"]="-----------------------------------\n-- ID: 14535\n-- onnagimi_yukata\n-- Dispense: Datechochin x99\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.itemBoxOnItemCheck(target)\nend\n\nitemObject.onItemUse = function(target)\n    npcUtil.giveItem(target, { { xi.item.DATECHOCHIN, 99 } })\nend\n\nreturn itemObject\n"},["scripts/items/opacus_cell.lua"]={["Path"]="scripts/items/opacus_cell.lua",["SHA256"]="847a0c632f3f1dbf218eb93a56e0a082a90239e89a7a04fc4f9a464ca383de2f",["Text"]="-----------------------------------\n-- Opacus Cell\n-- 5374\n-- Unlocks job abilities, weapon skills\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    if target:hasStatusEffect(xi.effect.IMPAIRMENT) then\n        return 0\n    end\n\n    return -1\nend\n\nitemObject.onItemUse = function(target)\n    target:delStatusEffectSilent(xi.effect.IMPAIRMENT)\n    target:messageText(target, zones[target:getZoneID()].text.CELL_OFFSET + 9)\nend\n\nreturn itemObject\n"},["scripts/items/opo-opo_tart.lua"]={["Path"]="scripts/items/opo-opo_tart.lua",["SHA256"]="d6f7e2a2650ac43a4861f10297f36fef0b7beea268f19aa78544dee38fdfd18e",["Text"]="-----------------------------------\n-- ID: 4287\n-- Item: opo-opo_tart\n-- Food Effect: 1hour, All Races\n-----------------------------------\n-- HP 12\n-- MP 12\n-- Intelligence 4\n-- MP Recovered While Healing 3\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 3600, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.FOOD_HP, 12)\n    effect:addMod(xi.mod.FOOD_MP, 12)\n    effect:addMod(xi.mod.INT, 4)\n    effect:addMod(xi.mod.MPHEAL, 3)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/orange_au_lait_tank.lua"]={["Path"]="scripts/items/orange_au_lait_tank.lua",["SHA256"]="770e2c3c3bb61c27cac154a19afaa8efdec77ef8fa3e5f4fddb1471433f24e56",["Text"]="-----------------------------------\n--  ID: 16223\n--  Orange au lait Tank\n--  When used, you will obtain one Orange au lait\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.itemBoxOnItemCheck(target)\nend\n\nitemObject.onItemUse = function(target)\n    npcUtil.giveItem(target, { { xi.item.FLASK_OF_ORANGE_AU_LAIT, 1 } })\nend\n\nreturn itemObject\n"},["scripts/items/orange_cake.lua"]={["Path"]="scripts/items/orange_cake.lua",["SHA256"]="6809aa06e6e9fdfe09929bd143742304b5b153a06fa634112873d40098a81f32",["Text"]="-----------------------------------\n-- ID: 5629\n-- Item: Orange Cake\n-- Food Effect: 3 Hrs, All Races\n-----------------------------------\n-- TODO: Group Effect\n-- HP Recovered while healing +3\n-- MP Recovered while healing +4\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 10800, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.HPHEAL, 3)\n    effect:addMod(xi.mod.MPHEAL, 4)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/orange_kuchen.lua"]={["Path"]="scripts/items/orange_kuchen.lua",["SHA256"]="7d404512ff90d88cea520fa23806a21e7e4937745189c1070f01ce4bcdb2b800",["Text"]="-----------------------------------\n-- ID: 4393\n-- Item: orange_kuchen\n-- Food Effect: 180Min, All Races\n-----------------------------------\n-- Magic % 13\n-- Magic Cap