in, All Races\n-----------------------------------\n-- MP +20% (cap 20)\n-- AGI -1\n-- INT +1\n-- Wind resistance +5\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 300, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.FOOD_MPP, 20)\n    effect:addMod(xi.mod.FOOD_MP_CAP, 20)\n    effect:addMod(xi.mod.AGI, -1)\n    effect:addMod(xi.mod.INT, 1)\n    effect:addMod(xi.mod.WIND_MEVA, 5)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/orc_piercer.lua"]={["Path"]="scripts/items/orc_piercer.lua",["SHA256"]="ea7effe1f2fcbb47c43dd574c7ef20065b19b87969e3129cc360cea1ae8d5d38",["Text"]="-----------------------------------\n-- ID: 16867\n-- Item: Orc Piercer\n-- Additional effect: light damage\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemAdditionalEffect = function(actor, target, baseAttackDamage, item)\n    if not target:isMob() or target:getFamily() ~= xi.mobFamily.ORC then\n        return 0, 0, 0\n    end\n\n    local dStat = actor:getStat(xi.mod.MND) - target:getStat(xi.mod.INT)\n    local pTable =\n    {\n        chance         = 10 + utils.clamp(dStat * 0.0926, 0, 5), -- 5% over 54 dMND\n        basePower      = math.randomInt(9, 12),\n        attackType     = xi.attackType.MAGICAL,\n        magicalElement = xi.element.LIGHT,\n        canMAB         = false,\n        canResist      = true,\n        lowestResist   = 0.5,\n    }\n\n    return xi.combat.action.executeAddEffectDamage(actor, target, pTable)\nend\n\nreturn itemObject\n"},["scripts/items/orichalcum_bullet_pouch.lua"]={["Path"]="scripts/items/orichalcum_bullet_pouch.lua",["SHA256"]="6119df678f28f3c8ac97db902aaaa034cdf4205f65742c67e73f6fd3cfb513d4",["Text"]="-----------------------------------\n-- ID: 5914\n-- Orichalcum Bullet Pouch\n-- When used, you will obtain one stack of Orichalcum Bullets\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.itemBoxOnItemCheck(target)\nend\n\nitemObject.onItemUse = function(target)\n    npcUtil.giveItem(target, { { xi.item.ORICHALCUM_BULLET, 99 } })\nend\n\nreturn itemObject\n"},["scripts/items/ornate_stool_set.lua"]={["Path"]="scripts/items/ornate_stool_set.lua",["SHA256"]="351402e65aa9e443890f917e47d4a1e006561d942f83baa2484d9d23cc7156bf",["Text"]="-----------------------------------\n-- ID: 6379\n-- Item: Ornate Stool\n-- Item Effect: Grant Ornate stool key item\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nlocal keyItemId = xi.keyItem.ORNATE_STOOL\n\nitemObject.onItemCheck = function(target, item, caster)\n    if target:hasKeyItem(keyItemId) then\n        return xi.msg.basic.ALREADY_HAVE_KEY_ITEM, 0, keyItemId\n    end\n\n    return 0\nend\n\nitemObject.onItemUse = function(target)\n    target:addKeyItem(keyItemId)\n    target:messageBasic(xi.msg.basic.OBTAINED_KEY_ITEM, 6379, keyItemId)\nend\n\nreturn itemObject\n"},["scripts/items/otoko_yukata.lua"]={["Path"]="scripts/items/otoko_yukata.lua",["SHA256"]="d4bd07f7edc019b8346c6e41d8b827750cb92c97b557e77f52f6cdfc6f507954",["Text"]="-----------------------------------\n-- ID: 14532\n-- otoko_yukata\n-- Dispense: Muteppo x99\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.itemBoxOnItemCheck(target)\nend\n\nitemObject.onItemUse = function(target)\n    npcUtil.giveItem(target, { { xi.item.MUTEPPO, 99 } })\nend\n\nreturn itemObject\n"},["scripts/items/otokogimi_yukata.lua"]={["Path"]="scripts/items/otokogimi_yukata.lua",["SHA256"]="fc4145971ac02b370000c520120420173a3ce4fa2609a029e3e138060a6e3d04",["Text"]="-----------------------------------\n-- ID: 14534\n-- otokogimi_yukata\n-- Dispense: Datechochin x99\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.itemBoxOnItemCheck(target)\nend\n\nitemObject.onItemUse = function(target)\n    npcUtil.giveItem(target, { { xi.item.DATECHOCHIN, 99 } })\nend\n\nreturn itemObject\n"},["scripts/items/ouka_ranman.lua"]={["Path"]="scripts/items/ouka_ranman.lua",["SHA256"]="4f54aaa66623d98c0179594b1f3365a7518a215d81029eb7b860e3a5816a8b7f",["Text"]="-----------------------------------\n-- ID: 4256\n-- Ouka Ranman\n-- Surrounds the user (and space in front of them) with falling cherry blossoms\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target)\nend\n\nreturn itemObject\n"},["scripts/items/oxidant_bolt_quiver.lua"]={["Path"]="scripts/items/oxidant_bolt_quiver.lua",["SHA256"]="99073fae49897194f892e5f18dd2984c0ed232c58033533fcd8deb47b7648366",["Text"]="-----------------------------------\n-- ID: 6141\n-- Item: O. Bolt Quiver\n-- When used, you will obtain one stack of Oxidant Bolts\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.itemBoxOnItemCheck(target)\nend\n\nitemObject.onItemUse = function(target)\n    npcUtil.giveItem(target, { { xi.item.OXIDANT_BOLT, 99 } })\nend\n\nreturn itemObject\n"},["scripts/items/pacifist_ring.lua"]={["Path"]="scripts/items/pacifist_ring.lua",["SHA256"]="7b4cf71b3beaf9cc1e663b362e1f93b8ed299c959f0401ca80b6befb4b45eb57",["Text"]="-----------------------------------\n-- ID: 14680\n-- Item: Pacifist Ring\n-- Item Effect: Enmity -12\n-- Duration: 3 Minutes\n-- https://wiki.ffo.jp/html/10070.html\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    if target:hasEquipped(xi.item.PACIFIST_RING) then\n        local effect = target:getStatusEffectBySource(xi.effect.ENCHANTMENT, xi.effectSourceType.EQUIPPED_ITEM, xi.item.PACIFIST_RING)\n        if effect then\n            effect:resetStartTime()\n        else\n            target:addStatusEffect(xi.effect.ENCHANTMENT, { duration = 180, origin = user, sourceType = xi.effectSourceType.EQUIPPED_ITEM, sourceTypeParam = xi.item.PACIFIST_RING })\n        end\n    end\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.ENMITY, -12)\nend\n\nitemObject.onItemUnequip = function(target, item)\n    target:delStatusEffect(xi.effect.ENCHANTMENT, nil, xi.effectSourceType.EQUIPPED_ITEM, xi.item.PACIFIST_RING)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/page_from_balrahns_reflections.lua"]={["Path"]="scripts/items/page_from_balrahns_reflections.lua",["SHA256"]="4646cde5da2baf921b6a7fe304ce859dc7e2835477938475e4c9b8b9dd405bd1",["Text"]="-----------------------------------\n-- ID: 5415\n-- Item:  Hero's Reflections\n-- Grants 200 - 500 EXP\n-- Source: https://wiki.ffo.jp/html/12204.html\n-- Does not grant Limit Points.\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    local check = 56\n    if target:getMainLvl() >= 60 then\n        check = 0\n    end\n\n    return check\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    local exp = xi.settings.main.EXP_RATE * math.randomInt(200, 500)\n\n    target:addExp(exp, false)\n    action:messageID(target:getID(), xi.msg.basic.ITEM_EXP_GAINED)\n\n    -- Show the full EXP amount even when EXP is capped.\n    return exp\nend\n\nreturn itemObject\n"},["scripts/items/page_from_miratetes_memoirs.lua"]={["Path"]="scripts/items/page_from_miratetes_memoirs.lua",["SHA256"]="1d76c9b30767dffc66cd80ffa985647c7eb7f13ae006b697af35e9d9c438b06a",["Text"]="-----------------------------------\n-- ID: 4247\n-- Item: Page From Miratete's Memoirs\n-- Grants 750 - 1,500 EXP\n-- Source: https://wiki.ffo.jp/html/2132.html\n-- Does not grant Limit Points.\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    local check = 56\n    if target:getMainLvl() >= 20 then\n        check = 0\n    end\n\n    return check\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    local exp = xi.settings.main.EXP_RATE * math.randomInt(750, 1500)\n\n    target:addExp(exp, false)\n    action:messageID(target:getID(), xi.msg.basic.ITEM_EXP_GAINED)\n\n    -- Show the full EXP amount even when EXP is capped.\n    return exp\nend\n\nreturn itemObject\n"},["scripts/items/page_from_the_dragon_chronicles.lua"]={["Path"]="scripts/items/page_from_the_dragon_chronicles.lua",["SHA256"]="5bbdeefd8efc2b2c965910ddfaadc40a686eb0589ae7bdb1e28b27a27dc7bb69",["Text"]="-----------------------------------\n-- ID: 4198\n-- Item: Page from the Dragon Chronicles\n-- Grants 500 - 1,000 EXP\n-- Source: https://wiki.ffo.jp/html/2144.html\n-- Does not grant Limit Points.\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    local check = 56\n    if target:getMainLvl() >= 4 then\n        check = 0\n    end\n\n    return check\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    local exp = xi.settings.main.EXP_RATE * math.randomInt(500, 1000)\n\n    target:addExp(exp, false)\n    action:messageID(target:getID(), xi.msg.basic.ITEM_EXP_GAINED)\n\n    -- Show the full EXP amount even when EXP is capped.\n    return exp\nend\n\nreturn itemObject\n"},["scripts/items/pair_of_lucid_wings_i.lua"]={["Path"]="scripts/items/pair_of_lucid_wings_i.lua",["SHA256"]="1a11487f5d3221f3f3282804b25738d8d7e6fffd58612e8df9d5268db2404502",["Text"]="-----------------------------------\n-- ID: 5834\n-- Item: pair_of_lucid_wings_i\n-- Item Effect: Grants 500 TP to Party members within 10'\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target)\n    target:forMembersInRange(10, function(member)\n        member:addTP(500)\n    end)\nend\n\nreturn itemObject\n"},["scripts/items/pair_of_lucid_wings_ii.lua"]={["Path"]="scripts/items/pair_of_lucid_wings_ii.lua",["SHA256"]="2f269461146771cde92f3881122b547f1249d49b76bd27bbd29a7f0c0ca34c81",["Text"]="-----------------------------------\n-- ID: 6475\n-- Item: pair_of_lucid_wings_ii\n-- Item Effect: Grants 1000 TP to Party members within 10'\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target)\n    target:forMembersInRange(10, function(member)\n        member:addTP(1000)\n    end)\nend\n\nreturn itemObject\n"},["scripts/items/pair_of_nopales.lua"]={["Path"]="scripts/items/pair_of_nopales.lua",["SHA256"]="57c11ab64beee3d486492fdda2c333416a2fd3d2d558baff6ab1488025ae4ffd",["Text"]="-----------------------------------\n-- ID: 5650\n-- Item: pair_of_nopales\n-- Food Effect: 5min, All Races\n-----------------------------------\n-- VIT -4\n-- AGI +2\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 300, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.VIT, -4)\n    effect:addMod(xi.mod.AGI, 2)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/paladin_die.lua"]={["Path"]="scripts/items/paladin_die.lua",["SHA256"]="de6683ec24bd518ef2efb7431f1f79e217e730061fe6c07e16676d8ec9dcccb1",["Text"]="-----------------------------------\n-- ID: 5483\n-- Paladin Die\n-- Teaches the job ability Gallant's Roll\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return target:canLearnAbility(xi.jobAbility.GALLANTS_ROLL)\nend\n\nitemObject.onItemUse = function(target)\n    target:addLearnedAbility(xi.jobAbility.GALLANTS_ROLL)\nend\n\nreturn itemObject\n"},["scripts/items/palmers_bangles.lua"]={["Path"]="scripts/items/palmers_bangles.lua",["SHA256"]="31ba3bbffca39216032b3f637053e3ab08d5c516c184ae9f169cbcb8a8271b26",["Text"]="-----------------------------------\n-- ID: 14864\n-- Item: Palmer's Bangles\n-- Item Effect: Gilfinder\n-- Duration: 3 Minutes\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, user)\n    if target:getStatusEffectBySource(xi.effect.ENCHANTMENT, xi.effectSourceType.EQUIPPED_ITEM, xi.item.PALMERS_BANGLES) ~= nil then\n        target:delStatusEffect(xi.effect.ENCHANTMENT, nil, xi.effectSourceType.EQUIPPED_ITEM, xi.item.PALMERS_BANGLES)\n    end\n\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    if target:hasEquipped(xi.item.PALMERS_BANGLES) then\n        target:addStatusEffect(xi.effect.ENCHANTMENT, { duration = 180, origin = user, sourceType = xi.effectSourceType.EQUIPPED_ITEM, sourceTypeParam = xi.item.PALMERS_BANGLES })\n    end\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.GILFINDER, 3)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/pamama_au_lait_tank.lua"]={["Path"]="scripts/items/pamama_au_lait_tank.lua",["SHA256"]="5a149e54ea55790b549cd5851b8ff0f5d274f605960167be676dd1d26282baa0",["Text"]="-----------------------------------\n-- ID: 16226\n-- Pamama Tank\n-- When used, you will obtain one Pamama au lait\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.itemBoxOnItemCheck(target)\nend\n\nitemObject.onItemUse = function(target)\n    npcUtil.giveItem(target, { { xi.item.FLASK_OF_PAMAMA_AU_LAIT, 1 } })\nend\n\nreturn itemObject\n"},["scripts/items/pamama_tart.lua"]={["Path"]="scripts/items/pamama_tart.lua",["SHA256"]="c3f0fff4e6c513c6d224155f1f463b8bb138fb510fe092c911aee34cedab0aa0",["Text"]="-----------------------------------\n-- ID: 4563\n-- Item: pamama_tart\n-- Food Effect: 1hour, All Races\n-----------------------------------\n-- HP 10\n-- MP 10\n-- Dexterity -1\n-- Intelligence 3\n-- MP Recovered While Healing 2\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 3600, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.FOOD_HP, 10)\n    effect:addMod(xi.mod.FOOD_MP, 10)\n    effect:addMod(xi.mod.DEX, -1)\n    effect:addMod(xi.mod.INT, 3)\n    effect:addMod(xi.mod.MPHEAL, 2)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/pannus_cell.lua"]={["Path"]="scripts/items/pannus_cell.lua",["SHA256"]="8b19b62812b473880fb227202d000a05d1783d0618e36df668bb0cf54d558c05",["Text"]="-----------------------------------\n-- Pannus Cell\n-- ID 5376\n-- Removes STR Down effect\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.salvage.onCellItemCheck(target, xi.effect.DEBILITATION, 0x001)\nend\n\nitemObject.onItemUse = function(target)\n    return xi.salvage.onCellItemUse(target, xi.effect.DEBILITATION, 0x001, 11)\nend\n\nreturn itemObject\n"},["scripts/items/papillion.lua"]={["Path"]="scripts/items/papillion.lua",["SHA256"]="8b7ad777df331fba2f5f5b6cba83a4faf9f563caece05ccef6a6df48f54ac8c6",["Text"]="-----------------------------------\n-- ID: 4257\n-- Papillion\n-- Adds butterfly wings to the user\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target)\nend\n\nreturn itemObject\n"},["scripts/items/party_egg.lua"]={["Path"]="scripts/items/party_egg.lua",["SHA256"]="b6da263237edcd071ca05ae1ae4fd5fa5f40949b3fd48ed0d3f37a59ab18bf08",["Text"]="-----------------------------------\n-- ID: 4595\n-- Item: party_egg\n-- Food Effect: 60Min, All Races\n-----------------------------------\n-- Health 25\n-- Magic 25\n-- Attack 5\n-- Ranged Attack 4\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 3600, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.FOOD_HP, 25)\n    effect:addMod(xi.mod.FOOD_MP, 25)\n    effect:addMod(xi.mod.ATT, 5)\n    effect:addMod(xi.mod.RATT, 4)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/pastoral_staff.lua"]={["Path"]="scripts/items/pastoral_staff.lua",["SHA256"]="77759405969a6fd0f41debafe02e36d4c263aa943e1808973c79bb659670e910",["Text"]="-----------------------------------\n-- ID: 18591\n-- Item: Pastoral Staff\n-- Item Effect: TP +100\n-- Duration: Instant\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target)\n    target:addTP(1000)\nend\n\nreturn itemObject\n"},["scripts/items/patio_design_plan_document.lua"]={["Path"]="scripts/items/patio_design_plan_document.lua",["SHA256"]="507cd9be31b68b5bda07090fce0ba9d54f7b8e7b5329c1d1e3bc3cb3b61f27e0",["Text"]="-----------------------------------\n-- ID: 6499\n-- Item: Patio design plan document\n-- Grants keyitem: MOG_PATIO_DESIGN_DOCUMENT\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    -- TODO: The error message returned by this is wrong\n    return target:hasKeyItem(xi.keyItem.MOG_PATIO_DESIGN_DOCUMENT) and 1 or 0\nend\n\nitemObject.onItemUse = function(target)\n    npcUtil.giveKeyItem(target, xi.keyItem.MOG_PATIO_DESIGN_DOCUMENT)\nend\n\nreturn itemObject\n"},["scripts/items/pear_au_lait_tank.lua"]={["Path"]="scripts/items/pear_au_lait_tank.lua",["SHA256"]="34aca898c78c6523258245c92c0492cb2940ed606b297ee5a05c48cd955d1730",["Text"]="-----------------------------------\n--  ID: 16225\n--  Pear au lait Tank\n--  When used, you will obtain one Pear au lait\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.itemBoxOnItemCheck(target)\nend\n\nitemObject.onItemUse = function(target)\n    npcUtil.giveItem(target, { { xi.item.FLASK_OF_PEAR_AU_LAIT, 1 } })\nend\n\nreturn itemObject\n"},["scripts/items/pear_crepe.lua"]={["Path"]="scripts/items/pear_crepe.lua",["SHA256"]="9474a791ce774cb9db9c25a5f707f1e2bb57a309f1f7ace2d43b87281879ee09",["Text"]="-----------------------------------\n-- ID: 5777\n-- Item: Pear Crepe\n-- Food Effect: 30 Min, All Races\n-----------------------------------\n-- Intelligence +2\n-- MP Healing +2\n-- Magic Accuracy +20% (cap 45)\n-- Magic Defense +1\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 1800, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.INT, 2)\n    effect:addMod(xi.mod.FOOD_MACCP, 20)\n    effect:addMod(xi.mod.FOOD_MACC_CAP, 45)\n    effect:addMod(xi.mod.MDEF, 1)\n    effect:addMod(xi.mod.MPHEAL, 2)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/pearlscale.lua"]={["Path"]="scripts/items/pearlscale.lua",["SHA256"]="c932f2c7c104a3b70521d4aecb617dbc7846c9ba0da8bf32db5d83a9f0be6736",["Text"]="-----------------------------------\n-- ID: 5714\n-- Item: Pearlscale\n-- Food Effect: 5 Min, Mithra only\n-----------------------------------\n-- Dexterity 2\n-- Mind -4\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.RAW_FISH)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 300, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.DEX, 2)\n    effect:addMod(xi.mod.MND, -4)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/pelican_ring.lua"]={["Path"]="scripts/items/pelican_ring.lua",["SHA256"]="4e3e6fc26211387c63f453ba015c37311a7ee86b407e07fc56a82d9fac71bf47",["Text"]="-----------------------------------\n-- ID: 15554\n-- Item: Pelican Ring\n-- Fishing Skillup Rate increase\n-----------------------------------\n-- Duration: 20:00 min\n-----------------------------------\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, user)\n    local pelicanStacks = target:countEffect(xi.effect.ENCHANTMENT, xi.item.PELICAN_RING)\n\n    if pelicanStacks >= 2 then\n        return xi.msg.basic.ITEM_UNABLE_TO_USE_2\n    end\n\n    return 0\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    local effect          = xi.effect.ENCHANTMENT\n    local power           = 0\n    local tick            = 0\n    local duration        = 1200\n    local subType         = xi.item.PELICAN_RING\n    local subPower        = 0\n    local tier            = 0\n    local flag            = xi.effectFlag.ON_ZONE\n\n    -- Allow for duplicate effects, max 2\n    if target:countEffect(effect, subType) < 2 then\n        target:addStatusEffect(effect, { power = power, duration = duration, origin = user, tick = tick, subType = subType, subPower = subPower, tier = tier, flag = flag })\n    end\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.PELICAN_RING_EFFECT, 1)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/pellet_belt.lua"]={["Path"]="scripts/items/pellet_belt.lua",["SHA256"]="7b903e21992f19b7824e2f352a6050fd1ffd45672b09c4288f5a3cf050324cb6",["Text"]="-----------------------------------\n--   ID: 15288\n--   Pellet Belt\n--   When used, you will obtain 12 Pebbles\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.itemBoxOnItemCheck(target)\nend\n\nitemObject.onItemUse = function(target)\n    npcUtil.giveItem(target, { { xi.item.PEBBLE, 12 } })\nend\n\nreturn itemObject\n"},["scripts/items/pendant_compass.lua"]={["Path"]="scripts/items/pendant_compass.lua",["SHA256"]="2c72f2e42418455665b4de20089dd9a9939f0e4aeb31af0936083131799329ac",["Text"]="-----------------------------------\n-- ID: 16285\n-- Pendant compass\n--  Use to determine your precise location in Vana'diel.\n--  Provides exact X, Y and Z location, where Y is the altitude.\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target)\n    target:showPosition()\nend\n\nreturn itemObject\n"},["scripts/items/pendragons_belt.lua"]={["Path"]="scripts/items/pendragons_belt.lua",["SHA256"]="7859da7f39ce8cc45931948cd1f852a2006cfba8eff6168934668b09ed4e4518",["Text"]="-----------------------------------\n-- ID: 15869\n-- Item: pendragons_belt\n-- Item Effect: DEX +10\n-- Duration: 60 seconds\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    if target:getStatusEffectBySource(xi.effect.ENCHANTMENT, xi.effectSourceType.EQUIPPED_ITEM, xi.item.PENDRAGONS_BELT) ~= nil then\n        target:delStatusEffect(xi.effect.ENCHANTMENT, nil, xi.effectSourceType.EQUIPPED_ITEM, xi.item.PENDRAGONS_BELT)\n    end\n\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    if target:hasEquipped(xi.item.PENDRAGONS_BELT) then\n        target:addStatusEffect(xi.effect.DEX_BOOST, { power = 10, duration = 60, origin = user, sourceType = xi.effectSourceType.EQUIPPED_ITEM, sourceTypeParam = xi.item.PENDRAGONS_BELT })\n    end\nend\n\nreturn itemObject\n"},["scripts/items/pepperoni_pizza.lua"]={["Path"]="scripts/items/pepperoni_pizza.lua",["SHA256"]="281a874183341d318bdb1f4cbdb25c6e73d1049a2fcf17e37616b21db9a8a028",["Text"]="-----------------------------------\n-- ID: 5697\n-- Item: pepperoni_pizza\n-- Food Effect: 3 hours, all Races\n-----------------------------------\n-- HP +30\n-- Strength 1\n-- Accuracy 9% (caps @ 10)\n-- Attack 10% (caps @ 15)\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 10800, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.FOOD_HP, 30)\n    effect:addMod(xi.mod.STR, 1)\n    effect:addMod(xi.mod.FOOD_ATTP, 10)\n    effect:addMod(xi.mod.FOOD_ATT_CAP, 15)\n    effect:addMod(xi.mod.FOOD_ACCP, 9)\n    effect:addMod(xi.mod.FOOD_ACC_CAP, 10)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/pepperoni_pizza_+1.lua"]={["Path"]="scripts/items/pepperoni_pizza_+1.lua",["SHA256"]="13b540302f47a255ec0bc15a00d9dc11a6e3e2bd10a909381b5f3d9e1036a263",["Text"]="-----------------------------------\n-- ID: 5698\n-- Item: pepperoni_pizza_+1\n-- Food Effect: 4 hours, all Races\n-----------------------------------\n-- HP +35\n-- Strength 2\n-- Accuracy 9% (caps @ 11)\n-- Attack 10% (caps @ 16)\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 14400, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.FOOD_HP, 35)\n    effect:addMod(xi.mod.STR, 2)\n    effect:addMod(xi.mod.FOOD_ATTP, 10)\n    effect:addMod(xi.mod.FOOD_ATT_CAP, 16)\n    effect:addMod(xi.mod.FOOD_ACCP, 9)\n    effect:addMod(xi.mod.FOOD_ACC_CAP, 11)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/perpetual_hourglass.lua"]={["Path"]="scripts/items/perpetual_hourglass.lua",["SHA256"]="88ed039dda1c1b587e1763f7e64dcf5ce09024c35a80e28810cce8268f243f7d",["Text"]="-----------------------------------\n-- ID: 4237\n-- Item: Perpetual Hourglass\n-- Use: Placeholder for Module\n-----------------------------------\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, param, caster)\n    return xi.dynamis.onGlassCheck(target, item)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    xi.dynamis.onGlassUse(target, item)\nend\n\nitemObject.onItemDrop = function(target, item)\n    xi.dynamis.onGlassDrop(target, item)\nend\n\nreturn itemObject\n"},["scripts/items/persikos.lua"]={["Path"]="scripts/items/persikos.lua",["SHA256"]="fb947455c6929fc4f0314b2e67ba0aa6d2ca9a7f6b9697eaba1c6704a461e7e9",["Text"]="-----------------------------------\n-- ID: 4274\n-- Item: persikos\n-- Food Effect: 5Min, All Races\n-----------------------------------\n-- Agility -7\n-- Intelligence 5\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 300, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.AGI, -7)\n    effect:addMod(xi.mod.INT, 5)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/persikos_au_lait_tank.lua"]={["Path"]="scripts/items/persikos_au_lait_tank.lua",["SHA256"]="dff6377b266b8e05a6a942e040d11896e4dd06976eb15baa2490a129a52bff6f",["Text"]="-----------------------------------\n-- ID: 16227\n-- Persikos Tank\n-- When used, you will obtain one Persikos au lait\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.itemBoxOnItemCheck(target)\nend\n\nitemObject.onItemUse = function(target)\n    npcUtil.giveItem(target, { { xi.item.FLASK_OF_PERSIKOS_AU_LAIT, 1 } })\nend\n\nreturn itemObject\n"},["scripts/items/persikos_snow_cone.lua"]={["Path"]="scripts/items/persikos_snow_cone.lua",["SHA256"]="f3ba7b3b0d355c88a357f05db56fabaaa395eec5e827af4ec6c2a8632af539e9",["Text"]="-----------------------------------\n-- ID: 6565\n-- Item: Persikos Snow Cone\n-- Food Effect: 5 minutes, all Races\n-----------------------------------\n-- MP +35% (Max. 50 @ 143 Base MP)\n-- INT +3\n-- [Element: Air]+5\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 300, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.FOOD_MPP, 35)\n    effect:addMod(xi.mod.FOOD_MP_CAP, 50)\n    effect:addMod(xi.mod.INT, 3)\n    effect:addMod(xi.mod.WIND_MEVA, 5)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/phial_of_amnesia_screen.lua"]={["Path"]="scripts/items/phial_of_amnesia_screen.lua",["SHA256"]="2ca355d5b9c1f02c8f1994fa09f170bab276acb5b620be2ff618ca9ba5d4bd8a",["Text"]="-----------------------------------\n-- ID: 5878\n-- Item: Amnesia Screen\n-- Effect: 2 Mins of immunity to \"Amnesia\" effects.\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    if target:hasStatusEffect(xi.effect.NEGATE_AMNESIA) then\n        return 56\n    end\n\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    target:addStatusEffect(xi.effect.NEGATE_AMNESIA, { power = 1, duration = 120, origin = user })\nend\n\nreturn itemObject\n"},["scripts/items/phial_of_doom_screen.lua"]={["Path"]="scripts/items/phial_of_doom_screen.lua",["SHA256"]="07cc798d81e4066dc69c7e4e94bf509d0644553926d57c837672dbd8074adbbe",["Text"]="-----------------------------------\n-- ID: 5879\n-- Item: Doom Screen\n-- Effect: 2 Mins of immunity to \"Doom\" effects.\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    if target:hasStatusEffect(xi.effect.NEGATE_DOOM) then\n        return 56\n    end\n\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    target:addStatusEffect(xi.effect.NEGATE_DOOM, { power = 1, duration = 120, origin = user })\nend\n\nreturn itemObject\n"},["scripts/items/phial_of_petrify_screen.lua"]={["Path"]="scripts/items/phial_of_petrify_screen.lua",["SHA256"]="f6e5997e4e0eaf38e1dc03441e9a21cb91827686e9413d422e2cd17ff975909b",["Text"]="-----------------------------------\n-- ID: 5876\n-- Item: Petrify Screen\n-- Effect: 2 Mins of immunity to \"Petrify\" effects.\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    if target:hasStatusEffect(xi.effect.NEGATE_PETRIFY) then\n        return 56\n    end\n\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    target:addStatusEffect(xi.effect.NEGATE_PETRIFY, { power = 1, duration = 120, origin = user })\nend\n\nreturn itemObject\n"},["scripts/items/phial_of_poison_screen.lua"]={["Path"]="scripts/items/phial_of_poison_screen.lua",["SHA256"]="92ea32bd97885634c26d98564207d26bff36523f7b7b6c9b3cbb3ce252b15608",["Text"]="-----------------------------------\n-- ID: 5880\n-- Item: Poison Screen\n-- Effect: 2 Mins of immunity to \"Poison\" effects.\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    if target:hasStatusEffect(xi.effect.NEGATE_POISON) then\n        return 56\n    end\n\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    target:addStatusEffect(xi.effect.NEGATE_POISON, { power = 1, duration = 120, origin = user })\nend\n\nreturn itemObject\n"},["scripts/items/phial_of_spectral_serum.lua"]={["Path"]="scripts/items/phial_of_spectral_serum.lua",["SHA256"]="5a3601a3485c713dd5cfdcb067ccea82a1108b255f50c360d88370a5aab45e73",["Text"]="-----------------------------------\n-- ID: 5352\n-- Phial of spectral Serum\n-- Enchantment: 60Min, Costume - ghost\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    if not target:canUseMisc(xi.zoneMisc.COSTUME) then\n        return xi.msg.basic.CANT_BE_USED_IN_AREA\n    end\n\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    target:addStatusEffect(xi.effect.COSTUME, { power = 368, duration = 3600, origin = user })\nend\n\nreturn itemObject\n"},["scripts/items/phial_of_terror_screen.lua"]={["Path"]="scripts/items/phial_of_terror_screen.lua",["SHA256"]="a32526694e183aa62dac7bd208111352af54562f75f51ac5228d427f4ec0b5e4",["Text"]="-----------------------------------\n-- ID: 5877\n-- Item: Terror Screen\n-- Effect: 2 Mins of immunity to \"Terror\" effects.\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    if target:hasStatusEffect(xi.effect.NEGATE_TERROR) then\n        return 56\n    end\n\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    target:addStatusEffect(xi.effect.NEGATE_TERROR, { power = 1, duration = 120, origin = user })\nend\n\nreturn itemObject\n"},["scripts/items/phial_of_volant_serum.lua"]={["Path"]="scripts/items/phial_of_volant_serum.lua",["SHA256"]="0f8e38a273554fa6d9ec2f9a24e9d42d3b1a829aa049ed75b431feb3f99b2043",["Text"]="-----------------------------------\n-- ID: 5350\n-- Phial of Volant Serum\n-- Enchantment: 60Min, Costume - bat\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    if not target:canUseMisc(xi.zoneMisc.COSTUME) then\n        return xi.msg.basic.CANT_BE_USED_IN_AREA\n    end\n\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    target:addStatusEffect(xi.effect.COSTUME, { power = 256, duration = 3600, origin = user })\nend\n\nreturn itemObject\n"},["scripts/items/pickled_herring.lua"]={["Path"]="scripts/items/pickled_herring.lua",["SHA256"]="b1a58e323fa692b01e70fabc637bc286fda457425d19254bd927e724871fcf68",["Text"]="-----------------------------------\n-- ID: 4490\n-- Item: Pickled Herring\n-- Food Effect: 30Min, All Races\n-----------------------------------\n-- Dexterity 3\n-- Mind -3\n-- Attack % 12 (cap 70)\n-- Ranged ATT % 12 (cap 70)\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 1800, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.DEX, 3)\n    effect:addMod(xi.mod.MND, -3)\n    effect:addMod(xi.mod.FOOD_ATTP, 12)\n    effect:addMod(xi.mod.FOOD_ATT_CAP, 70)\n    effect:addMod(xi.mod.FOOD_RATTP, 12)\n    effect:addMod(xi.mod.FOOD_RATT_CAP, 70)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"}};
